import test,{before,after}from"node:test";import assert from"node:assert/strict";import type{FastifyInstance}from"fastify";import{PostgreSqlContainer,type StartedPostgreSqlContainer}from"@testcontainers/postgresql";import type{Pool}from"pg";
let db:StartedPostgreSqlContainer,app:FastifyInstance,pool:Pool,cookie="";
const TEST_BOOTSTRAP_SECRET="test_bootstrap_secret_123456";
const png=(text="data")=>Buffer.concat([Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]),Buffer.from(text)]),pdf=(text="data")=>Buffer.from(`%PDF-1.4\n${text}`);
const nid=(prefix:string)=>{const r=prefix.split("").reduce((n,d,i)=>n+Number(d)*(10-i),0)%11,c=r<2?r:11-r;return prefix+c};
const family=(n:number)=>({caseNumber:`T-${n}`,familySurname:`آزمایشی ${n}`,headName:`سرپرست آزمایشی ${n}`,headNationalId:nid(String(100000000+n).padStart(9,"0")),headBirthDate:"1360/01/01",headPhone:"09120000000",familyPhone:"",headEducation:{},headJob:"",insurance:{},housingType:"other",housingDeposit:0,housingRent:0,address:"تهران",notes:"",priority:"متوسط",members:[],notesHistory:[]});
const inject=(o:any)=>app.inject({...o,headers:{cookie,...("headers"in o?o.headers:{}),"content-type":"application/json"}});
async function createFamily(n:number){const r=await inject({method:"POST",url:"/api/families",payload:family(n)});assert.equal(r.statusCode,201,r.body);return r.json().familyId as string}
async function financial(fid:string,amount:number){const r=await inject({method:"POST",url:`/api/families/${fid}/financial-cases`,payload:{title:"کمک آزمایشی",category:"کمک نقدی",amount,jalaliYear:1405,jalaliMonth:7,description:"",institutionNote:""}});assert.equal(r.statusCode,201,r.body);const id=r.json().financialCaseId;for(const action of["review","approve","refer"]){const x=await inject({method:"POST",url:`/api/financial-cases/${id}/transition`,payload:{action}});assert.equal(x.statusCode,200,x.body)}return id as string}
async function fund(name:string,budget:number){const r=await inject({method:"POST",url:"/api/funds",payload:{name,description:"تست"}});assert.equal(r.statusCode,201,r.body);const id=r.json().fundId;const b=await inject({method:"PUT",url:`/api/funds/${id}/budget`,payload:{jalaliYear:1405,jalaliMonth:7,amount:budget}});assert.equal(b.statusCode,200,b.body);return id as string}
const pay=(caseId:string,fundId:string,key:string)=>inject({method:"POST",url:`/api/financial-cases/${caseId}/pay`,headers:{"idempotency-key":key},payload:{fundId,jalaliYear:1405,jalaliMonth:7,paidAt:"2026-09-22",referenceNo:key,note:"",receipt:null}});
before(async()=>{db=await new PostgreSqlContainer("postgres:16-alpine").withDatabase("family_case_test").withUsername("family_app").withPassword("test_password").start();process.env.NODE_ENV="test";process.env.DATABASE_URL=db.getConnectionUri();process.env.CORS_ORIGIN="http://127.0.0.1:3000";process.env.COOKIE_SECURE="false";process.env.BOOTSTRAP_SECRET=TEST_BOOTSTRAP_SECRET;const database=await import("../src/db.js"),m=await import("../src/migrations.js"),a=await import("../src/app.js");pool=database.pool;await m.runMigrations(pool);app=await a.buildApp({logger:false,serveStatic:false});await app.ready()});
after(async()=>{await app?.close();await pool?.end();await db?.stop()});
test("health and readiness contracts",async()=>{assert.deepEqual((await app.inject({method:"GET",url:"/health"})).json(),{ok:true,check:"process"});assert.equal((await app.inject({method:"GET",url:"/ready"})).statusCode,200)});
test("bootstrap, login, family lifecycle and duplicate handling",async()=>{const boot=await app.inject({method:"POST",url:"/auth/bootstrap",payload:{displayName:"مدیر تست",username:"admin",password:"StrongPass123",installSecret:TEST_BOOTSTRAP_SECRET}});assert.equal(boot.statusCode,200,boot.body);cookie=String(boot.headers["set-cookie"]).split(";")[0]??"";const login=await app.inject({method:"POST",url:"/auth/login",payload:{username:"admin",password:"StrongPass123"}});assert.equal(login.statusCode,200);const id=await createFamily(1),dup=await inject({method:"POST",url:"/api/families",payload:family(1)});assert.equal(dup.statusCode,409);assert.equal((await inject({method:"POST",url:`/api/families/${id}/archive`,payload:{reason:"تست آرشیو"}})).statusCode,200);const{notesHistory,...edit}=family(1);assert.equal((await inject({method:"PATCH",url:`/api/families/${id}`,payload:edit})).statusCode,409);assert.equal((await inject({method:"POST",url:`/api/families/${id}/unarchive`,payload:{reason:"تست بازگردانی"}})).statusCode,200)});
test("same financial case cannot be paid twice concurrently",async()=>{const fid=await createFamily(2),cid=await financial(fid,600),fundId=await fund("صندوق همزمانی پرونده",1000),responses=await Promise.all([pay(cid,fundId,"same-case-0001"),pay(cid,fundId,"same-case-0002")]);assert.deepEqual(responses.map(x=>x.statusCode).sort(),[201,409]);const q=await pool.query("SELECT count(*)::int n,sum(amount)::int total FROM financial_payments WHERE financial_case_id=$1",[cid]);assert.equal(q.rows[0].n,1);assert.equal(q.rows[0].total,600)});
test("concurrent payments never exceed monthly budget",async()=>{const f1=await createFamily(3),f2=await createFamily(4),c1=await financial(f1,600),c2=await financial(f2,600),fundId=await fund("صندوق محدود",1000),responses=await Promise.all([pay(c1,fundId,"budget-case-01"),pay(c2,fundId,"budget-case-02")]);assert.deepEqual(responses.map(x=>x.statusCode).sort(),[201,409]);const q=await pool.query("SELECT sum(amount)::int total FROM financial_payments WHERE fund_id=$1",[fundId]);assert.equal(q.rows[0].total,600);const audit=await inject({method:"GET",url:`/api/families/${responses[0].statusCode===201?f1:f2}/audit`});assert.equal(audit.statusCode,200);assert.ok(audit.json().events.some((x:{action:string})=>x.action==="financial.payment"))});

test("logout invalidates session",async()=>{const login=await app.inject({method:"POST",url:"/auth/login",payload:{username:"admin",password:"StrongPass123"}}),c=String(login.headers["set-cookie"]).split(";")[0]??"";assert.equal((await app.inject({method:"POST",url:"/auth/logout",headers:{cookie:c}})).statusCode,200);assert.equal((await app.inject({method:"GET",url:"/api/families",headers:{cookie:c}})).statusCode,401)});

test("role permissions, user management and session invalidation",async()=>{const users=[['worker1','caseworker'],['account1','accountant'],['viewer1','viewer'],['worker2','caseworker']]as const,ids:Record<string,string>={};for(const[u,role]of users){const r=await inject({method:"POST",url:"/api/users",payload:{username:u,displayName:u,password:"StrongPass123",role}});assert.equal(r.statusCode,201,r.body);ids[u]=r.json().userId}const login=async(u:string)=>{const r=await app.inject({method:"POST",url:"/auth/login",payload:{username:u,password:"StrongPass123"}});assert.equal(r.statusCode,200,r.body);return String(r.headers["set-cookie"]).split(";")[0]??""},viewer=await login('viewer1'),accountant=await login('account1'),worker=await login('worker1');assert.equal((await app.inject({method:"POST",url:"/api/families",headers:{cookie:viewer},payload:family(20)})).statusCode,403);assert.equal((await app.inject({method:"POST",url:"/api/families",headers:{cookie:accountant},payload:family(21)})).statusCode,403);assert.equal((await app.inject({method:"POST",url:"/api/funds",headers:{cookie:worker},payload:{name:"غیرمجاز",description:""}})).statusCode,403);assert.equal((await app.inject({method:"GET",url:"/api/users",headers:{cookie:viewer}})).statusCode,403);assert.equal((await inject({method:"PATCH",url:`/api/users/${ids.viewer1}`,payload:{active:false}})).statusCode,200);assert.equal((await app.inject({method:"GET",url:"/api/families",headers:{cookie:viewer}})).statusCode,401)});

test("financial rejection and invalid transitions are deterministic",async()=>{const fid=await createFamily(30),r=await inject({method:"POST",url:`/api/families/${fid}/financial-cases`,payload:{title:"رد آزمایشی",category:"سایر",amount:"۱۰۰۰",jalaliYear:"۱۴۰۵",jalaliMonth:"۷",description:"",institutionNote:""}}),id=r.json().financialCaseId;assert.equal((await inject({method:"POST",url:`/api/financial-cases/${id}/transition`,payload:{action:"approve"}})).statusCode,409);assert.equal((await inject({method:"POST",url:`/api/financial-cases/${id}/transition`,payload:{action:"review"}})).statusCode,200);assert.equal((await inject({method:"POST",url:`/api/financial-cases/${id}/transition`,payload:{action:"reject"}})).statusCode,400);assert.equal((await inject({method:"POST",url:`/api/financial-cases/${id}/transition`,payload:{action:"reject",reason:"عدم احراز شرایط"}})).statusCode,200)});

test("ordinary budget exceeded, money strings, receipt and idempotency replay",async()=>{const f1=await createFamily(31),c1=await financial(f1,600),small=await fund("بودجه ناکافی عادی",500);assert.equal((await pay(c1,small,"ordinary-budget-1")).statusCode,409);const f2=await createFamily(32),c2=await financial(f2,400),ok=await fund("صندوق Idempotency",1000),payload={fundId:ok,jalaliYear:1405,jalaliMonth:7,paidAt:"2026-09-22",referenceNo:"REF-100",note:"رسید تست",receipt:{fileName:"receipt.png",mimeType:"image/png",contentBase64:png("receipt").toString("base64")}},first=await inject({method:"POST",url:`/api/financial-cases/${c2}/pay`,headers:{"idempotency-key":"idem-real-0001"},payload}),again=await inject({method:"POST",url:`/api/financial-cases/${c2}/pay`,headers:{"idempotency-key":"idem-real-0001"},payload});assert.equal(first.statusCode,201,first.body);assert.equal(again.statusCode,201,again.body);assert.equal(first.json().paymentId,again.json().paymentId);assert.equal(again.headers["idempotency-replayed"],"true");const changed=await inject({method:"POST",url:`/api/financial-cases/${c2}/pay`,headers:{"idempotency-key":"idem-real-0001"},payload:{...payload,referenceNo:"DIFFERENT"}});assert.equal(changed.statusCode,409);assert.equal(changed.json().error,"IDEMPOTENCY_KEY_REUSED");const list=await inject({method:"GET",url:`/api/families/${f2}/financial-cases`}),item=list.json().financialCases[0];assert.equal(typeof item.amount,"string");assert.equal(typeof list.json().paidAmount,"string");const receipt=await inject({method:"GET",url:`/api/payments/${first.json().paymentId}/receipt`,headers:{"x-access-reason":"بررسی رسید پرداخت"}});assert.equal(receipt.statusCode,200);assert.ok(receipt.rawPayload.subarray(0,8).equals(png("").subarray(0,8)))});

test("sensitive documents obey assignment and archive rules",async()=>{const users=await inject({method:"GET",url:"/api/users"}),worker1=users.json().users.find((x:{username:string})=>x.username==='worker1'),worker2=users.json().users.find((x:{username:string})=>x.username==='worker2'),login=async(u:string)=>String((await app.inject({method:"POST",url:"/auth/login",payload:{username:u,password:"StrongPass123"}})).headers["set-cookie"]).split(";")[0]??"",w1=await login('worker1'),w2=await login('worker2'),fid=await createFamily(40);assert.equal((await inject({method:"POST",url:`/api/families/${fid}/notes`,payload:{text:"تخصیص",status:"",institutionNote:"",followUpStatus:"باز",assigneeId:worker1.id}})).statusCode,201);const upload=await inject({method:"POST",url:`/api/families/${fid}/documents`,payload:{fileName:"secret.png",mimeType:"image/png",category:"شناسایی",description:"",sensitive:true,contentBase64:png("secret").toString("base64")}});assert.equal(upload.statusCode,201,upload.body);const did=upload.json().documentId;assert.equal((await app.inject({method:"GET",url:`/api/documents/${did}/download`,headers:{cookie:w1,"x-access-reason":"پیگیری پرونده خانواده"}})).statusCode,200);assert.equal((await app.inject({method:"GET",url:`/api/documents/${did}/download`,headers:{cookie:w2,"x-access-reason":"بررسی غیرمجاز"}})).statusCode,403);assert.equal((await inject({method:"POST",url:`/api/families/${fid}/archive`,payload:{reason:"تست اسناد آرشیوی"}})).statusCode,200);assert.equal((await app.inject({method:"POST",url:`/api/families/${fid}/documents`,headers:{cookie:w1},payload:{fileName:"x.png",mimeType:"image/png",category:"سایر",description:"",sensitive:false,contentBase64:Buffer.from("x").toString("base64")}})).statusCode,409);assert.ok(worker2)});

test("audit log is immutable",async()=>{await assert.rejects(pool.query("UPDATE audit_logs SET action='tampered' WHERE id=(SELECT min(id) FROM audit_logs)"));await assert.rejects(pool.query("DELETE FROM audit_logs WHERE id=(SELECT min(id) FROM audit_logs)"))});

test("Persian and Arabic digits normalize before validation",async()=>{const ascii=nid("222222223"),faDigits=(v:string)=>v.replace(/\d/g,d=>"۰۱۲۳۴۵۶۷۸۹"[Number(d)]!),payload={...family(50),caseNumber:"۵۰",headNationalId:faDigits(ascii),headPhone:"۰۹۱۲۱۲۳۴۵۶۷"},r=await inject({method:"POST",url:"/api/families",payload});assert.equal(r.statusCode,201,r.body);const q=await pool.query("SELECT case_number,head_national_id,head_phone FROM families WHERE id=$1",[r.json().familyId]);assert.equal(q.rows[0].case_number,"50");assert.equal(q.rows[0].head_national_id,ascii);assert.equal(q.rows[0].head_phone,"09121234567")});

test("archived sensitive documents remain readable but immutable",async()=>{const q=await pool.query("SELECT d.id FROM family_documents d JOIN families f ON f.id=d.family_id WHERE d.sensitive AND f.archived LIMIT 1");assert.equal(q.rowCount,1);assert.equal((await inject({method:"GET",url:`/api/documents/${q.rows[0].id}/download`,headers:{"x-access-reason":"بازبینی سند آرشیوی"}})).statusCode,200);const accountant=String((await app.inject({method:"POST",url:"/auth/login",payload:{username:"account1",password:"StrongPass123"}})).headers["set-cookie"]).split(";")[0]??"";assert.equal((await app.inject({method:"GET",url:`/api/documents/${q.rows[0].id}/download`,headers:{cookie:accountant,"x-access-reason":"بررسی سند"}})).statusCode,403)});

test("bootstrap cannot run twice and expired sessions are rejected",async()=>{assert.equal((await app.inject({method:"POST",url:"/auth/bootstrap",payload:{displayName:"دوم",username:"second",password:"StrongPass123",installSecret:TEST_BOOTSTRAP_SECRET}})).statusCode,409);const login=await app.inject({method:"POST",url:"/auth/login",payload:{username:"worker2",password:"StrongPass123"}}),c=String(login.headers["set-cookie"]).split(";")[0]??"";await pool.query("UPDATE sessions SET expires_at=now()-interval '1 minute' WHERE user_id=(SELECT id FROM users WHERE username='worker2')");assert.equal((await app.inject({method:"GET",url:"/api/families",headers:{cookie:c}})).statusCode,401)});


test("C.1 liaison-supervisor-family scope and specialist referrals",async()=>{const users=await inject({method:"GET",url:"/api/users"}),worker1=users.json().users.find((x:{username:string})=>x.username==='worker1'),worker2=users.json().users.find((x:{username:string})=>x.username==='worker2');assert.equal(worker1.position,"liaison");const healthCreate=await inject({method:"POST",url:"/api/users",payload:{username:"health1",displayName:"مسئول درمان",password:"StrongPass123",role:"caseworker",position:"health_officer"}});assert.equal(healthCreate.statusCode,201,healthCreate.body);const login=async(u:string)=>{const r=await app.inject({method:"POST",url:"/auth/login",payload:{username:u,password:"StrongPass123"}});assert.equal(r.statusCode,200,r.body);return String(r.headers["set-cookie"]).split(";")[0]??""},w1=await login("worker1"),w2=await login("worker2"),health=await login("health1"),supervisor=await inject({method:"POST",url:"/api/supervisors",payload:{name:"سرپرست اول",phone:"09120000001",liaisonId:worker1.id}});assert.equal(supervisor.statusCode,201,supervisor.body);const fid=await createFamily(60);assert.equal((await inject({method:"POST",url:`/api/families/${fid}/supervisor`,payload:{supervisorId:supervisor.json().supervisorId,reason:"تخصیص اولیه"}})).statusCode,200);const list1=await app.inject({method:"GET",url:"/api/families",headers:{cookie:w1}}),list2=await app.inject({method:"GET",url:"/api/families",headers:{cookie:w2}});assert.ok(list1.json().families.some((x:{id:string})=>x.id===fid));assert.ok(!list2.json().families.some((x:{id:string})=>x.id===fid));assert.equal((await app.inject({method:"GET",url:`/api/families/${fid}`,headers:{cookie:w2}})).statusCode,403);assert.equal((await app.inject({method:"GET",url:`/api/families/${fid}`,headers:{cookie:health}})).statusCode,403);const referral=await app.inject({method:"POST",url:`/api/families/${fid}/referrals`,headers:{cookie:w1},payload:{domain:"health",assignedTo:healthCreate.json().userId,reason:"نیاز به بررسی درمانی"}});assert.equal(referral.statusCode,201,referral.body);assert.equal((await app.inject({method:"GET",url:`/api/families/${fid}`,headers:{cookie:health}})).statusCode,200);assert.equal((await app.inject({method:"PATCH",url:`/api/referrals/${referral.json().referralId}`,headers:{cookie:health},payload:{status:"done"}})).statusCode,200);assert.equal((await app.inject({method:"GET",url:`/api/families/${fid}`,headers:{cookie:health}})).statusCode,403);const supervisor2=await inject({method:"POST",url:"/api/supervisors",payload:{name:"سرپرست دوم",phone:"09120000002",liaisonId:worker2.id}});assert.equal((await inject({method:"POST",url:`/api/families/${fid}/supervisor`,payload:{supervisorId:supervisor2.json().supervisorId,reason:"تغییر سرپرست"}})).statusCode,200);const history=await pool.query("SELECT count(*)::int total,count(*) FILTER(WHERE ends_at IS NULL)::int active FROM family_supervisor_assignments WHERE family_id=$1",[fid]);assert.equal(history.rows[0].total,2);assert.equal(history.rows[0].active,1);assert.equal((await app.inject({method:"GET",url:`/api/families/${fid}`,headers:{cookie:w1}})).statusCode,403);assert.equal((await app.inject({method:"GET",url:`/api/families/${fid}`,headers:{cookie:w2}})).statusCode,200)});

test("C.2 weekly indirect report requires deputy approval",async()=>{const deputyCreate=await inject({method:"POST",url:"/api/users",payload:{username:"deputy1",displayName:"معاون سرپرستی",password:"StrongPass123",role:"caseworker",position:"supervision_deputy"}});assert.equal(deputyCreate.statusCode,201,deputyCreate.body);const login=async(u:string)=>{const r=await app.inject({method:"POST",url:"/auth/login",payload:{username:u,password:"StrongPass123"}});assert.equal(r.statusCode,200,r.body);return String(r.headers["set-cookie"]).split(";")[0]??""},liaison=await login("worker2"),other=await login("worker1"),deputy=await login("deputy1"),health=await login("health1"),familyRow=await pool.query("SELECT id FROM families WHERE case_number='T-60'"),fid=familyRow.rows[0].id,payload={weekStart:"2026-09-19",contactAt:"2026-09-22T08:00:00.000Z",contactMethod:"phone",checklist:{contactSuccessful:true,housingChange:"none",incomeChange:"worse",healthConcern:true,educationConcern:false,urgentNeed:false,notes:"کاهش درآمد گزارش شد"},priority:"high",summary:"گزارش هفتگی از طریق سرپرست دریافت شد",proposedActions:"پیگیری درمان و درآمد"};assert.equal((await app.inject({method:"POST",url:`/api/families/${fid}/supervision-reports`,headers:{cookie:other},payload})).statusCode,403);const created=await app.inject({method:"POST",url:`/api/families/${fid}/supervision-reports`,headers:{cookie:liaison},payload});assert.equal(created.statusCode,201,created.body);const rid=created.json().reportId;assert.equal((await app.inject({method:"POST",url:`/api/supervision-reports/${rid}/submit`,headers:{cookie:liaison},payload:{}})).statusCode,200);assert.equal((await app.inject({method:"POST",url:`/api/supervision-reports/${rid}/review`,headers:{cookie:health},payload:{decision:"approve",note:""}})).statusCode,403);assert.equal((await app.inject({method:"POST",url:`/api/supervision-reports/${rid}/review`,headers:{cookie:deputy},payload:{decision:"revision",note:""}})).statusCode,400);assert.equal((await app.inject({method:"POST",url:`/api/supervision-reports/${rid}/review`,headers:{cookie:deputy},payload:{decision:"revision",note:"جزئیات درآمد تکمیل شود"}})).statusCode,200);assert.equal((await app.inject({method:"PATCH",url:`/api/supervision-reports/${rid}`,headers:{cookie:liaison},payload:{summary:"گزارش اصلاح‌شده هفتگی از طریق سرپرست"}})).statusCode,200);assert.equal((await app.inject({method:"POST",url:`/api/supervision-reports/${rid}/submit`,headers:{cookie:liaison},payload:{}})).statusCode,200);const inbox=await app.inject({method:"GET",url:"/api/supervision/inbox",headers:{cookie:deputy}});assert.ok(inbox.json().pending.some((x:{id:string})=>x.id===rid));assert.equal((await app.inject({method:"POST",url:`/api/supervision-reports/${rid}/review`,headers:{cookie:deputy},payload:{decision:"approve",note:"تأیید شد"}})).statusCode,200);const q=await pool.query("SELECT r.status,p.next_due_at::text AS due FROM supervision_reports r JOIN family_supervision_plans p ON p.family_id=r.family_id WHERE r.id=$1",[rid]);assert.equal(q.rows[0].status,"approved");assert.equal(q.rows[0].due,"2026-09-29")});
test("C.3 action plan assignment, completion, approval and specialist access cutoff",async()=>{const login=async(u:string)=>{const r=await app.inject({method:"POST",url:"/auth/login",payload:{username:u,password:"StrongPass123"}});assert.equal(r.statusCode,200,r.body);return String(r.headers["set-cookie"]).split(";")[0]??""},liaison=await login("worker2"),deputy=await login("deputy1"),health=await login("health1"),rows=await pool.query(`SELECT r.id report_id,r.family_id,u.id health_id FROM supervision_reports r CROSS JOIN users u WHERE r.status='approved' AND u.username='health1' ORDER BY r.reviewed_at DESC LIMIT 1`);assert.equal(rows.rowCount,1);const x=rows.rows[0],created=await app.inject({method:"POST",url:`/api/supervision-reports/${x.report_id}/actions`,headers:{cookie:liaison},payload:{title:"پیگیری درمان تخصصی",description:"بررسی و تکمیل روند درمان",domain:"health"}});assert.equal(created.statusCode,201,created.body);const id=created.json().actionId,assigned=await app.inject({method:"POST",url:`/api/actions/${id}/assign`,headers:{cookie:deputy},payload:{assigneeId:x.health_id,dueDate:"2026-10-01",note:"رسیدگی درمانی"}});assert.equal(assigned.statusCode,200,assigned.body);assert.equal((await app.inject({method:"GET",url:`/api/families/${x.family_id}`,headers:{cookie:health}})).statusCode,200);assert.equal((await app.inject({method:"POST",url:`/api/actions/${id}/complete`,headers:{cookie:health},payload:{result:"درمان انجام شد و نتیجه ثبت گردید"}})).statusCode,200);assert.equal((await app.inject({method:"POST",url:`/api/actions/${id}/review`,headers:{cookie:deputy},payload:{decision:"approve",note:"نتیجه مورد تأیید است"}})).statusCode,200);assert.equal((await app.inject({method:"GET",url:`/api/families/${x.family_id}`,headers:{cookie:health}})).statusCode,403);const q=await pool.query("SELECT status FROM case_actions WHERE id=$1",[id]);assert.equal(q.rows[0].status,"approved")});

