test("C.9 security, privacy, direct-object access and file validation controls",async()=>{const weak=await inject({method:"POST",url:"/api/users",payload:{username:"weakuser",displayName:"کاربر ضعیف",password:"shortpass",role:"viewer"}});assert.equal(weak.statusCode,400);const badFile=await inject({method:"POST",url:"/api/families/"+(await pool.query("SELECT id FROM families WHERE case_number='T-60'")).rows[0].id+"/documents",payload:{fileName:"fake.png",mimeType:"image/png",category:"سایر",description:"",sensitive:false,contentBase64:Buffer.from("<script>alert(1)</script>").toString("base64")}});assert.equal(badFile.statusCode,400);assert.equal(badFile.json().error,"FILE_CONTENT_REJECTED");const doc=(await pool.query("SELECT id,sha256,scan_status FROM family_documents WHERE sensitive ORDER BY created_at DESC LIMIT 1")).rows[0];assert.equal(doc.scan_status,"clean");assert.match(doc.sha256,/^[a-f0-9]{64}$/);const noReason=await inject({method:"GET",url:`/api/documents/${doc.id}/download`});assert.equal(noReason.statusCode,400);assert.equal(noReason.json().error,"ACCESS_REASON_REQUIRED");const withReason=await inject({method:"GET",url:`/api/documents/${doc.id}/download`,headers:{"x-access-reason":"کنترل نهایی امنیت سند"}});assert.equal(withReason.statusCode,200);assert.ok((await pool.query("SELECT 1 FROM sensitive_access_logs WHERE resource_id=$1 AND access_reason=$2",[doc.id,"کنترل نهایی امنیت سند"])).rowCount);const workerLogin=await app.inject({method:"POST",url:"/auth/login",payload:{username:"worker1",password:"StrongPass123"}}),workerCookie=String(workerLogin.headers["set-cookie"]).split(";")[0]??"",payment=(await pool.query("SELECT id FROM financial_payments WHERE receipt_data IS NOT NULL ORDER BY created_at LIMIT 1")).rows[0];assert.equal((await app.inject({method:"GET",url:`/api/payments/${payment.id}/receipt`,headers:{cookie:workerCookie,"x-access-reason":"تلاش کنترل دسترسی"}})).statusCode,403);const policy=await inject({method:"GET",url:"/api/security/retention-policy"});assert.equal(policy.statusCode,200);assert.equal(policy.json().policy.backupEncryptionRequired,true);assert.equal((await app.inject({method:"GET",url:"/api/security/retention-policy",headers:{cookie:workerCookie}})).statusCode,403);const preview=await inject({method:"GET",url:"/api/security/retention-preview"});assert.equal(preview.statusCode,200);assert.equal(preview.json().dryRun,true);const changed=await inject({method:"PATCH",url:"/api/users/"+(await pool.query("SELECT id FROM users WHERE username='viewer1'")).rows[0].id,payload:{position:"viewer"}});assert.equal(changed.statusCode,200);const audit=(await pool.query("SELECT details FROM audit_logs WHERE action='user.update' AND entity_id=(SELECT id FROM users WHERE username='viewer1') ORDER BY id DESC LIMIT 1")).rows[0].details;assert.ok(audit.before&&audit.after)});

test("C.10 migration preview validates rows, imports linked records and reconciles provenance",async()=>{const template=await inject({method:"GET",url:"/api/data-migration/template"});assert.equal(template.statusCode,200);assert.match(template.rawPayload.toString(),/recordType/);const invalid=await inject({method:"POST",url:"/api/data-migration/preview",payload:{sourceName:"invalid.csv",sourceType:"csv",rows:[{recordType:"family",caseNumber:"M-BAD",familySurname:"ناقص",headName:"سرپرست",headNationalId:"123",headPhone:"09120000000"}]}});assert.equal(invalid.statusCode,201,invalid.body);assert.equal(invalid.json().invalid,1);assert.equal(invalid.json().canExecute,false);assert.equal((await inject({method:"POST",url:`/api/data-migration/batches/${invalid.json().batchId}/execute`,payload:{}})).statusCode,409);const head=nid("333333331"),member=nid("333333332"),rows=[{recordType:"liaison",username:"migrate-liaison",displayName:"رابط مهاجرت"},{recordType:"supervisor",supervisorCode:"MS-1",name:"سرپرست مهاجرت",phone:"09121111111",liaisonUsername:"migrate-liaison"},{recordType:"family",caseNumber:"M-100",familySurname:"مهاجرتی",headName:"سرپرست مهاجرتی",headNationalId:head,headPhone:"09122222222",supervisorCode:"MS-1",housingType:"other",housingDeposit:0,housingRent:0,priority:"متوسط"},{recordType:"member",familyCaseNumber:"M-100",name:"عضو مهاجرتی",nationalId:member,relation:"فرزند"}],preview=await inject({method:"POST",url:"/api/data-migration/preview",payload:{sourceName:"migration-test.csv",sourceType:"csv",rows}});assert.equal(preview.statusCode,201,preview.body);assert.equal(preview.json().valid,4);assert.equal(preview.json().invalid,0);assert.equal(preview.json().canExecute,true);const executed=await inject({method:"POST",url:`/api/data-migration/batches/${preview.json().batchId}/execute`,payload:{}});assert.equal(executed.statusCode,200,executed.body);assert.equal(executed.json().imported,4);assert.equal(executed.json().temporaryCredentials.length,1);const linked=await pool.query(`SELECT f.import_source,m.import_batch_id,s.import_batch_id,u.must_change_password FROM families f JOIN family_members m ON m.family_id=f.id JOIN family_supervisor_assignments fa ON fa.family_id=f.id AND fa.ends_at IS NULL JOIN supervisors s ON s.id=fa.supervisor_id JOIN users u ON u.id=s.liaison_id WHERE f.case_number='M-100'`);assert.equal(linked.rowCount,1);assert.equal(linked.rows[0].import_source,"migration-test.csv");assert.equal(linked.rows[0].must_change_password,true);const report=await inject({method:"GET",url:`/api/data-migration/batches/${preview.json().batchId}/report`});assert.equal(report.statusCode,200,report.body);assert.equal(report.json().batch.status,"completed");assert.equal(report.json().batch.imported,4)});

test("C.11 role-based UAT records results, feedback, prioritization and RC readiness",async()=>{const cycle=await inject({method:"POST",url:"/api/uat/cycles",payload:{name:"پذیرش نسخه C11",targetVersion:"v17.0.0",includeDefaults:true}});assert.equal(cycle.statusCode,201,cycle.body);assert.equal(cycle.json().scenariosCreated,7);const cycleId=cycle.json().cycleId;assert.equal((await inject({method:"POST",url:`/api/uat/cycles/${cycleId}/activate`,payload:{}})).statusCode,200);const login=await app.inject({method:"POST",url:"/auth/login",payload:{username:"worker2",password:"StrongPass123"}}),liaisonCookie=String(login.headers["set-cookie"]).split(";")[0]??"",scenarios=await app.inject({method:"GET",url:`/api/uat/cycles/${cycleId}/scenarios`,headers:{cookie:liaisonCookie}});assert.equal(scenarios.statusCode,200,scenarios.body);assert.ok(scenarios.json().scenarios.length>0);assert.ok(scenarios.json().scenarios.every((x:{position:string})=>x.position==="liaison"));const sid=scenarios.json().scenarios[0].id;assert.equal((await app.inject({method:"PUT",url:`/api/uat/scenarios/${sid}/result`,headers:{cookie:liaisonCookie},payload:{status:"passed",notes:"سناریوی رابط تأیید شد",evidence:{screen:"manual"}}})).statusCode,200);const feedback=await app.inject({method:"POST",url:"/api/uat/feedback",headers:{cookie:liaisonCookie},payload:{cycleId,scenarioId:sid,category:"ux",severity:"normal",title:"بهبود متن دکمه",description:"عنوان دکمه برای کاربر روشن‌تر شود"}});assert.equal(feedback.statusCode,201,feedback.body);assert.equal((await inject({method:"PATCH",url:`/api/uat/feedback/${feedback.json().feedbackId}`,payload:{status:"triaged",priorityRank:5,resolutionNote:"برای اصلاح بعدی ثبت شد"}})).statusCode,200);const summary=await inject({method:"GET",url:`/api/uat/cycles/${cycleId}/summary`});assert.equal(summary.statusCode,200,summary.body);assert.equal(summary.json().readiness.ready,false);assert.ok(summary.json().feedback.some((x:{priorityRank:number})=>x.priorityRank===5));const rc=await inject({method:"POST",url:`/api/uat/cycles/${cycleId}/release-candidate`,payload:{version:"17.0.0-rc.1"}});assert.equal(rc.statusCode,409);assert.equal(rc.json().error,"UAT_NOT_READY")});

test("C.12 production operations expose secured health metrics and security headers",async()=>{const status=await inject({method:"GET",url:"/api/ops/status"});assert.equal(status.statusCode,200,status.body);assert.equal(status.json().ok,true);assert.equal(status.json().database.status,"up");assert.equal(typeof status.json().http.requests,"number");assert.equal(status.headers["x-content-type-options"],"nosniff");assert.equal(status.headers["x-frame-options"],"DENY");const metrics=await inject({method:"GET",url:"/api/ops/metrics"});assert.equal(metrics.statusCode,200,metrics.body);assert.match(metrics.rawPayload.toString(),/family_case_http_requests_total/);const worker=await app.inject({method:"POST",url:"/auth/login",payload:{username:"worker1",password:"StrongPass123"}}),workerCookie=String(worker.headers["set-cookie"]).split(";")[0]??"";assert.equal((await app.inject({method:"GET",url:"/api/ops/status",headers:{cookie:workerCookie}})).statusCode,403)});

test("C.13 role training, acknowledgement and handover checklist are auditable",async()=>{const login=await app.inject({method:"POST",url:"/auth/login",payload:{username:"worker2",password:"StrongPass123"}}),liaisonCookie=String(login.headers["set-cookie"]).split(";")[0]??"",modules=await app.inject({method:"GET",url:"/api/training/modules",headers:{cookie:liaisonCookie}});assert.equal(modules.statusCode,200,modules.body);const liaisonModule=modules.json().modules.find((x:{code:string})=>x.code==="liaison");assert.ok(liaisonModule);const document=await app.inject({method:"GET",url:liaisonModule.documentUrl,headers:{cookie:liaisonCookie}});assert.equal(document.statusCode,200,document.body);assert.match(document.json().content,/راهنمای رابط/);assert.equal((await app.inject({method:"POST",url:"/api/training/modules/liaison/acknowledge",headers:{cookie:liaisonCookie},payload:{}})).statusCode,200);const refreshed=await app.inject({method:"GET",url:"/api/training/modules",headers:{cookie:liaisonCookie}});assert.ok(refreshed.json().modules.find((x:{code:string})=>x.code==="liaison").acknowledgedAt);const progress=await inject({method:"GET",url:"/api/training/progress"});assert.equal(progress.statusCode,200,progress.body);assert.ok(progress.json().users.find((x:{username:string})=>x.username==="worker2").acknowledged>=1);const checklist=await inject({method:"GET",url:"/api/handover/checklist"});assert.equal(checklist.statusCode,200,checklist.body);assert.equal(checklist.json().summary.ready,false);const item=checklist.json().items[0];assert.equal((await inject({method:"PUT",url:`/api/handover/checklist/${item.code}`,payload:{completed:true,evidenceNote:"در محیط تست تأیید شد"}})).statusCode,200);const updated=await inject({method:"GET",url:"/api/handover/checklist"});assert.ok(updated.json().items.find((x:{code:string})=>x.code===item.code).completed);assert.equal((await app.inject({method:"GET",url:"/api/handover/checklist",headers:{cookie:liaisonCookie}})).statusCode,403)});

test("C.14 future extensions are private, transactional and provider-ready",async()=>{const pub=await app.inject({method:"POST",url:"/public/support-requests",payload:{applicantName:"متقاضی تست",phone:"09121234567",nationalId:"1234567890",summary:"درخواست حمایت عمومی برای آزمون سامانه"}});assert.equal(pub.statusCode,201,pub.body);const status=await app.inject({method:"GET",url:`/public/support-requests/${pub.json().trackingCode}/status`});assert.equal(status.statusCode,200);assert.equal(status.json().phone,undefined);const login=await app.inject({method:"POST",url:"/auth/login",payload:{username:"worker2",password:"StrongPass123"}}),worker=String(login.headers["set-cookie"]).split(";")[0]??"";assert.equal((await app.inject({method:"GET",url:"/api/future/dashboard",headers:{cookie:worker}})).statusCode,403);const donor=await inject({method:"POST",url:"/api/donors",payload:{name:"حامی C14",donorType:"individual",phone:"",email:"",notes:""}});assert.equal(donor.statusCode,201,donor.body);const donation=await inject({method:"POST",url:"/api/donations",payload:{donorId:donor.json().donorId,donationType:"cash",amount:1000,description:"کمک تست"}});assert.equal(donation.statusCode,201,donation.body);const did=donation.json().donationId;assert.equal((await inject({method:"POST",url:`/api/donations/${did}/receive`,payload:{}})).statusCode,200);const fid=(await pool.query("SELECT id FROM families WHERE case_number='T-60'")).rows[0].id;assert.equal((await inject({method:"POST",url:`/api/donations/${did}/allocate`,payload:{familyId:fid,amount:700,note:""}})).statusCode,201);assert.equal((await inject({method:"POST",url:`/api/donations/${did}/allocate`,payload:{familyId:fid,amount:400,note:""}})).statusCode,409);const item=await inject({method:"POST",url:"/api/inventory/items",payload:{name:"بسته C14",unit:"بسته",minimumStock:2}});assert.equal(item.statusCode,201,item.body);const iid=item.json().itemId;assert.equal((await inject({method:"POST",url:"/api/inventory/transactions",payload:{itemId:iid,type:"receipt",quantity:10,note:""}})).statusCode,201);assert.equal((await inject({method:"POST",url:"/api/inventory/transactions",payload:{itemId:iid,type:"issue",quantity:3,familyId:fid,note:""}})).statusCode,201);assert.equal((await inject({method:"POST",url:"/api/inventory/transactions",payload:{itemId:iid,type:"issue",quantity:8,familyId:fid,note:""}})).statusCode,409);const msg=await inject({method:"POST",url:"/api/notifications/outbox",payload:{channel:"sms",recipient:"09121234567",templateKey:"support_update",payload:{tags:["c14","test"]}}});assert.equal(msg.statusCode,202,msg.body);assert.deepEqual((await pool.query("SELECT payload FROM notification_outbox WHERE id=$1",[msg.json().notificationId])).rows[0].payload.tags,["c14","test"]);assert.equal((await inject({method:"PATCH",url:`/api/families/${fid}/geography`,payload:{latitude:35.6892,longitude:51.389}})).statusCode,200);assert.ok((await inject({method:"GET",url:"/api/families/map"})).json().families.some((x:{id:string})=>x.id===fid));assert.equal((await inject({method:"GET",url:"/api/future/dashboard"})).statusCode,200)});

test("authentication rate limit returns 429",async()=>{let last;for(let i=0;i<11;i++)last=await app.inject({method:"POST",url:"/auth/login",payload:{username:"missing-user",password:"WrongPass123"}});assert.equal(last!.statusCode,429)});